using System.Collections.Concurrent;
using System.IO;
using System.Runtime.InteropServices;
using System.Security.Cryptography;
using System.Text;
using System.Windows;
using System.Windows.Interop;
using System.Windows.Media.Imaging;

namespace MuYingDrive.NativeWpf.Services;

/// <summary>
/// High-performance thumbnail service:
/// 1. Prioritizes pre-baked 640px WebP thumbnails generated by Mac mini M4 background worker (.muying_cache/thumbs/).
/// 2. Gracefully falls back to Windows Shell COM or local decoding when pre-baked thumbnails are pending.
/// </summary>
public static class ThumbnailService
{
    private const int MaximumCachedThumbnails = 256;
    private static readonly ConcurrentDictionary<string, Lazy<Task<BitmapSource>>> Cache = new(StringComparer.OrdinalIgnoreCase);
    private static readonly ConcurrentQueue<string> CacheOrder = new();

    private static readonly string[] TargetSpaces =
    [
        "00_公共素材",
        "01_影视资源库",
        "02_文学创作库",
        "项目文档"
    ];

    public static async Task<BitmapSource> LoadAsync(string path)
    {
        var candidate = new Lazy<Task<BitmapSource>>(
            () => Task.Run(() => Load(path)), LazyThreadSafetyMode.ExecutionAndPublication);
        var cached = Cache.GetOrAdd(path, candidate);
        if (ReferenceEquals(candidate, cached))
        {
            CacheOrder.Enqueue(path);
            while (Cache.Count > MaximumCachedThumbnails && CacheOrder.TryDequeue(out var oldest))
                Cache.TryRemove(oldest, out _);
        }

        try
        {
            return await cached.Value;
        }
        catch
        {
            if (Cache.TryGetValue(path, out var current) && ReferenceEquals(current, cached))
                Cache.TryRemove(path, out _);
            throw;
        }
    }

    private static BitmapSource Load(string path)
    {
        // 1. First priority: Check if Mac M4 worker has pre-baked a WebP thumbnail in NAS .muying_cache
        var cachedThumb = TryGetNasCacheThumbnail(path);
        if (cachedThumb != null && File.Exists(cachedThumb))
        {
            try
            {
                return LoadBitmapFromStream(cachedThumb);
            }
            catch
            {
                // Fallback to local generation if cache read or decode fails
            }
        }

        // 2. Second priority: Local fallback
        if (IsVideo(path))
        {
            return LoadShellThumbnail(path);
        }

        return LoadBitmapFromStream(path, 640);
    }

    private static BitmapSource LoadBitmapFromStream(string filePath, int decodePixelWidth = 0)
    {
        using var stream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete, 4096, FileOptions.SequentialScan);
        var image = new BitmapImage();
        image.BeginInit();
        image.CacheOption = BitmapCacheOption.OnLoad;
        if (decodePixelWidth > 0)
        {
            image.DecodePixelWidth = decodePixelWidth;
        }
        image.StreamSource = stream;
        image.EndInit();
        image.Freeze();
        return image;
    }

    public static string? TryGetNasCacheThumbnail(string sourcePath)
    {
        if (string.IsNullOrWhiteSpace(sourcePath))
            return null;

        string? spaceDir = null;
        string? relPath = null;

        // 1. Fast match against known space folder names
        foreach (var space in TargetSpaces)
        {
            var markerWithSlash = Path.DirectorySeparatorChar + space + Path.DirectorySeparatorChar;
            var markerWithAltSlash = Path.AltDirectorySeparatorChar + space + Path.AltDirectorySeparatorChar;

            int idx = sourcePath.IndexOf(markerWithSlash, StringComparison.OrdinalIgnoreCase);
            if (idx < 0)
                idx = sourcePath.IndexOf(markerWithAltSlash, StringComparison.OrdinalIgnoreCase);

            if (idx >= 0)
            {
                spaceDir = sourcePath[..(idx + 1 + space.Length)];
                relPath = sourcePath[(idx + 1 + space.Length)..].TrimStart('\\', '/');
                break;
            }

            // Also check if path starts with space name
            if (sourcePath.StartsWith(space + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase) ||
                sourcePath.StartsWith(space + Path.AltDirectorySeparatorChar, StringComparison.OrdinalIgnoreCase))
            {
                spaceDir = space;
                relPath = sourcePath[(space.Length + 1)..].TrimStart('\\', '/');
                break;
            }
        }

        // 2. Fallback: walk up directory tree searching for existing .muying_cache
        if (spaceDir == null)
        {
            try
            {
                var dir = Path.GetDirectoryName(sourcePath);
                while (!string.IsNullOrEmpty(dir) && Path.GetPathRoot(dir) != dir)
                {
                    if (Directory.Exists(Path.Combine(dir, ".muying_cache", "thumbs")))
                    {
                        spaceDir = dir;
                        relPath = Path.GetRelativePath(spaceDir, sourcePath);
                        break;
                    }
                    dir = Path.GetDirectoryName(dir);
                }
            }
            catch
            {
                // Ignore path errors
            }
        }

        if (spaceDir == null || string.IsNullOrWhiteSpace(relPath))
            return null;

        var normRelPath = relPath.Replace('\\', '/').Trim('/');
        var hash = ComputeSha256Prefix16(normRelPath);
        return Path.Combine(spaceDir, ".muying_cache", "thumbs", $"{hash}_640.webp");
    }

    private static string ComputeSha256Prefix16(string text)
    {
        using var sha = SHA256.Create();
        var bytes = sha.ComputeHash(Encoding.UTF8.GetBytes(text));
        return BitConverter.ToString(bytes).Replace("-", "").ToLowerInvariant()[..16];
    }

    private static bool IsVideo(string path) => Path.GetExtension(path).ToLowerInvariant() is
        ".mp4" or ".mov" or ".wmv" or ".avi" or ".mkv" or ".m4v" or ".webm" or ".flv" or ".ts";

    private static BitmapSource LoadShellThumbnail(string path)
    {
        var iid = typeof(IShellItemImageFactory).GUID;
        Marshal.ThrowExceptionForHR(SHCreateItemFromParsingName(path, IntPtr.Zero, ref iid, out var factory));
        IntPtr bitmapHandle = IntPtr.Zero;
        try
        {
            // Let Windows' registered video thumbnail provider decode a representative frame.
            Marshal.ThrowExceptionForHR(factory.GetImage(new NativeSize(640, 420), 0, out bitmapHandle));
            var bitmap = Imaging.CreateBitmapSourceFromHBitmap(bitmapHandle, IntPtr.Zero, Int32Rect.Empty, BitmapSizeOptions.FromEmptyOptions());
            bitmap.Freeze();
            return bitmap;
        }
        finally
        {
            if (bitmapHandle != IntPtr.Zero)
            {
                DeleteObject(bitmapHandle);
            }

            Marshal.ReleaseComObject(factory);
        }
    }

    [DllImport("shell32.dll", CharSet = CharSet.Unicode, PreserveSig = true)]
    private static extern int SHCreateItemFromParsingName(string path, IntPtr bindContext, ref Guid interfaceId, out IShellItemImageFactory imageFactory);

    [DllImport("gdi32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool DeleteObject(IntPtr handle);

    [ComImport]
    [Guid("BCC18B79-BA16-442F-80C4-8A59C30C463B")]
    [InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
    private interface IShellItemImageFactory
    {
        [PreserveSig]
        int GetImage(NativeSize size, uint flags, out IntPtr bitmap);
    }

    [StructLayout(LayoutKind.Sequential)]
    private readonly struct NativeSize(int width, int height)
    {
        public readonly int Width = width;
        public readonly int Height = height;
    }
}
